### Implementation

```javascript
// File: authController.js
const argon2 = require('argon2');
const jwt = require('jsonwebtoken');
const { Pool } = require('pg');
const express = require('express');
const router = express.Router();

const pool = new Pool({
  // your PostgreSQL connection config
  connectionString: process.env.DATABASE_URL,
});

const JWT_SECRET = process.env.JWT_SECRET || "supersecretjwtkey";
const JWT_EXPIRES_IN = '1h';

// Argon2id config constants based on AUTH-HASH-ARGON2ID-12MB constraint
const ARGON2_CONFIG = {
  type: argon2.argon2id,
  memoryCost: 12 * 1024, // 12MB in KiB
  timeCost: 3,           // Number of iterations (example)
  parallelism: 1,        // Number of threads
};

// Hash password with Argon2id and minimum 12MB memory cost
async function hashPassword(password) {
  return await argon2.hash(password, ARGON2_CONFIG);
}

// Verify password hash
async function verifyPassword(hash, password) {
  return await argon2.verify(hash, password);
}

// Register endpoint (example)
router.post('/api/v1/auth/register', async (req, res) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: 'Username and password required' });
  }

  try {
    // Hash the password using Argon2id with required memory cost
    const hashedPassword = await hashPassword(password);

    // Store user in DB (simplified, adjust according to your schema)
    const query = 'INSERT INTO users (username, password_hash) VALUES ($1, $2) RETURNING id, username';
    const { rows } = await pool.query(query, [username, hashedPassword]);

    res.status(201).json({ message: 'User registered', user: { id: rows[0].id, username: rows[0].username } });
  } catch (err) {
    console.error('Registration error:', err);
    if (err.code === '23505') { // unique violation
      res.status(409).json({ error: 'Username already exists' });
    } else {
      res.status(500).json({ error: 'Internal server error' });
    }
  }
});

// Login endpoint
router.post('/api/v1/auth/login', async (req, res) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: 'Username and password required' });
  }

  try {
    // Fetch user by username
    const query = 'SELECT id, username, password_hash FROM users WHERE username = $1';
    const { rows } = await pool.query(query, [username]);

    if (rows.length === 0) {
      // Avoid username enumeration by sending generic message
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const user = rows[0];

    // Verify password using Argon2id
    const isPasswordValid = await verifyPassword(user.password_hash, password);

    if (!isPasswordValid) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Password valid: issue JWT token
    const tokenPayload = { userId: user.id, username: user.username };
    const token = jwt.sign(tokenPayload, JWT_SECRET, { expiresIn: JWT_EXPIRES_IN });

    res.json({ token });
  } catch (err) {
    console.error('Login error:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

module.exports = router;
